-- 【给前端同学】和 schema-h2.sql 是「同一张表的两份方言写法」，字段完全一致。
-- 区别：这个文件**不会自动执行**。切到 MySQL profile 时，需按 README 手工执行一次：
--   mysql -uroot -p students < src/main/resources/schema-mysql.sql
-- 原因见 application-mysql.yml 的 spring.sql.init.mode: never。

-- 第一行是给你复制用的提示（被注释掉了）：先建数据库，指定 utf8mb4 字符集以完整支持中文
-- CREATE DATABASE students DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS students (          -- 建表，表名/字段与 H2 版一一对应
  id         BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '学号',
  -- ↑ MySQL 的自增写法是 AUTO_INCREMENT（H2 写成 GENERATED BY DEFAULT AS IDENTITY）；
  --   PRIMARY KEY 仍是主键；COMMENT 是给列加中文备注，只影响可读性，不影响功能
  name       VARCHAR(50) NOT NULL COMMENT '姓名',        -- 姓名，必填
  age        INT         NOT NULL COMMENT '年龄',        -- 年龄，必填
  class_name VARCHAR(50) NOT NULL COMMENT '班级',       -- 班级；下划线列名 ↔ 前端 className 靠驼峰映射
  phone      VARCHAR(20) NOT NULL COMMENT '电话'        -- 电话，字符串类型
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学生表';
-- ↑ ENGINE=InnoDB：MySQL 的存储引擎（支持事务，Service 上的 @Transactional 依赖它）
--   DEFAULT CHARSET=utf8mb4：默认字符集，utf8mb4 才能完整存中文和 emoji
--   COMMENT：表备注
-- 这几项是 MySQL 专有配置，H2 版没有，所以才需要两份建表脚本。
